{
  "title": "Monday at the stations",
  "width": 900,
  "height": 120,
  "controls": [
    { "type": "label", "label": "How it works", "text": "Drag through Monday. Every station starts the day with 20 bikes; the board shows how many are left at each hour.", "x": 0, "y": 0, "width": 900, "height": 44 },
    { "type": "slider", "label": "Time", "bind": "bikes_hour", "default": 9, "min": 6, "max": 23, "step": 1, "suffix": ":00", "x": 0, "y": 54, "width": 520, "height": 64 }
  ]
}

const hourly = nb.get('bikes_hourly');
if (!hourly) return 'Run the Clojure week cell above first.';

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: 'Journeys starting each hour, on an average day',
  width: 'container',
  height: 240,
  data: { values: hourly },
  mark: { type: 'line', point: true, strokeWidth: 2.5, interpolate: 'monotone' },
  encoding: {
    x: { field: 'hour', type: 'quantitative', title: 'Hour of the day', scale: { domain: [6, 22] }, axis: { tickCount: 16, labelExpr: "datum.value + ':00'" } },
    y: { field: 'journeys', type: 'quantitative', title: 'Journeys' },
    color: { field: 'day_type', type: 'nominal', title: null, scale: { domain: ['weekday', 'weekend'], range: ['#2563eb', '#f97316'] } },
    tooltip: [
      { field: 'day_type', title: 'Day' },
      { field: 'hour', title: 'Hour' },
      { field: 'journeys', title: 'Journeys', format: '.1f' },
    ],
  },
};
